DROP POLICY IF EXISTS "autenticati manutenzioni" ON public.manutenzioni;
CREATE POLICY "owner all" ON public.manutenzioni FOR ALL TO authenticated USING (public.is_app_owner()) WITH CHECK (public.is_app_owner());
